const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const n = input[0];
let pos = 1;
let root = null;
let previousPenalty = 0;
const output = [];

let seed = 123456789;
function randomPriority() {
  seed ^= seed << 13;
  seed ^= seed >>> 17;
  seed ^= seed << 5;
  return seed >>> 0;
}

function size(node) {
  return node ? node.size : 0;
}

function update(node) {
  node.size = node.count + size(node.left) + size(node.right);
  return node;
}

function rotateRight(node) {
  const child = node.left;
  node.left = child.right;
  child.right = update(node);
  return update(child);
}

function rotateLeft(node) {
  const child = node.right;
  node.right = child.left;
  child.left = update(node);
  return update(child);
}

function insert(node, key) {
  if (!node) {
    return {
      key,
      priority: randomPriority(),
      count: 1,
      size: 1,
      left: null,
      right: null
    };
  }

  if (key === node.key) {
    node.count++;
  } else if (key < node.key) {
    node.left = insert(node.left, key);
    if (node.left.priority > node.priority) node = rotateRight(node);
  } else {
    node.right = insert(node.right, key);
    if (node.right.priority > node.priority) node = rotateLeft(node);
  }

  return update(node);
}

function countAtMost(node, key) {
  let result = 0;
  while (node) {
    if (key < node.key) {
      node = node.left;
    } else {
      result += size(node.left) + node.count;
      node = node.right;
    }
  }
  return result;
}

for (let i = 0; i < n; i++) {
  const x = input[pos++] + previousPenalty;
  const y = input[pos++] + previousPenalty;
  const distanceSquared = x * x + y * y;

  const penalty = countAtMost(root, distanceSquared);
  output.push(String(penalty));
  root = insert(root, distanceSquared);
  previousPenalty = penalty;
}

process.stdout.write(output.join('\n'));
